const fs = require('fs');
const path = require('path');
const ts = require('/rules/node_modules/typescript');
const files = [];
function walk(dir) { for (const name of fs.readdirSync(dir)) { const p = path.join(dir, name); const st = fs.statSync(p); if (st.isDirectory()) walk(p); else if (/\\.(ets|ts)"'$/.test(name)) files.push(p); } }
walk('"'entry/src/main/ets');
let errors = 0;
for (const file of files) {
  const text = fs.readFileSync(file, 'utf8');
  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS);
  const diagnostics = sf.parseDiagnostics || [];
  for (const d of diagnostics) { errors++; console.log("'`${file}:${sf.getLineAndCharacterOfPosition(d.start || 0).line + 1}: ${ts.flattenDiagnosticMessageText(d.messageText, '"' ')}"'`); }
}
console.log(`Parsed ${files.length} files; syntax diagnostics: ${errors}`);
process.exitCode = errors ? 1 : 0;
NODE'

