/usr/bin/bash -lc "node - <<'NODE'
const fs=require('fs');
const s=JSON.parse(fs.readFileSync('.exp_agent/round_01/completion-schema.json','utf8'));
const r=JSON.parse(fs.readFileSync('.exp_agent/round_01/completion.json','utf8'));
const required=s.required;
const failures=[];
for(const k of required) if("'!(k in r)) failures.push(`missing ${k}`);
if(!Array.isArray(r.blocked)||r.blocked.length) failures.push('"'blocked not empty');
if("'!Array.isArray(r.unresolved_external)||r.unresolved_external.length) failures.push('"'unresolved_external not empty');
for(const [i,e] of r.entity_repairs.entries()) {
  for(const k of ['rule','relative_path','locations','entities','evidence','transformation','status']) if("'!(k in e)) failures.push(`entry ${i} missing ${k}`);
  if(!Array.isArray(e.locations)||!e.locations.length||!Array.isArray(e.entities)||!e.entities.length||!Array.isArray(e.evidence)||!e.evidence.length||!e.transformation||e.status!=='"'repaired') failures.push("'`entry ${i} invalid values`);
}
console.log(failures.length ? failures.join('"'\\n') : 'manual schema checks: valid');
console.log("'`entries=${r.entity_repairs.length}, locations=${r.entity_repairs.reduce((n,e)=>n+e.locations.length,0)}`);
